// Parses budget strings like "3.9K" or "1.2M" into a plain number.
const parseBudget = (value: string): number => {
  const match = value.trim().match(/^([\d.,]+)\s*([KkMm]?)$/);
  if (!match) return 0;
  const base = parseFloat(match[1].replace(/,/g, ""));
  if (Number.isNaN(base)) return 0;
  const suffix = match[2].toUpperCase();
  if (suffix === "M") return base * 1_000_000;
  if (suffix === "K") return base * 1_000;
  return base;
};

// Formats a plain number back into the K / M style used by the table.
const formatBudget = (total: number): string => {
  if (total >= 1_000_000) return `${(total / 1_000_000).toFixed(1)}M`;
  if (total >= 1_000) return `${(total / 1_000).toFixed(1)}K`;
  return total.toFixed(0);
};

const totalBudget = formatBudget(
  tableData.reduce((sum, order) => sum + parseBudget(order.budget), 0),
);

